import fs from 'fs/promises';
import { realpathSync } from 'fs';
import path from 'path';
import { createHash } from 'crypto';
import { glob } from 'glob';
import { resolveCommand, type Agent } from 'package-manager-detector';
import { DevServerStartError } from '../utils/devServerError';
import { selectedOperatingSystemServices } from './OperatingSystemServices';
import {
  INSTALL_ARTIFACTS,
  INSTALL_CONFIG_FILES,
  INSTALL_CONTENT_GLOBS,
  LOCKFILES,
  forEveryPackageManager,
  readProjectFile,
  resolveProjectPackageManager,
  type ProjectPackageManager,
} from './ProjectPackageManager';
import { errnoCode } from '../utils/errnoCode';
import { isPathWithinRoot } from '../utils/pathContainment';
import { errorMessage } from '../utils/errorMessage';
import {
  failureReasonCode,
  type FailureReasonCode,
} from '../utils/failureReason';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';

interface PrepareOptions {
  cwd: string;
  workspaceRoot: string;
  packageManagerCommand?: string;
  force?: boolean;
  signal?: AbortSignal;
}

interface PreparationResult {
  status: 'prepared' | 'reused' | 'skipped';
  packageManager?: ProjectPackageManager;
}

const MAX_CONCURRENT_INSTALLS = 2;
const INSTALL_TIMEOUT_MS = 5 * 60 * 1000;
const VERSION_TIMEOUT_MS = 20_000;
const TERMINATION_SETTLE_TIMEOUT_MS = 5_000;
const OUTPUT_TAIL_LIMIT = 4_000;
const LOCKFILE_NAMES = new Set(forEveryPackageManager(LOCKFILES));
const INPUT_FILES = [
  'package.json',
  ...LOCKFILE_NAMES,
  ...forEveryPackageManager(INSTALL_CONFIG_FILES),
];
const INSTALL_ARTIFACT_PATHS = forEveryPackageManager(INSTALL_ARTIFACTS);
const INSTALL_CONTENT_GLOB_PATTERNS = forEveryPackageManager(
  INSTALL_CONTENT_GLOBS,
);
const INSTALL_ENVIRONMENT_PREFIXES = [
  'npm_config_',
  'yarn_',
  'pnpm_',
  'corepack_',
];
const INSTALL_ENVIRONMENT_KEYS = new Set(['node_options', 'path']);

interface InstallFailureCause {
  reasonCode: FailureReasonCode;
  pattern: RegExp;
  guidance: string;
}

const INSTALL_FAILURE_CAUSES: readonly InstallFailureCause[] = [
  {
    reasonCode: 'lockfile_outdated',
    pattern:
      /^error Your lockfile needs to be updated, but yarn was run with `--frozen-lockfile`/m,
    guidance:
      'The lockfile does not match package.json. Update the lockfile in the project, commit it, then retry the preview.',
  },
  {
    reasonCode: 'engine_incompatible',
    pattern: /^error .+: The engine "node" is incompatible with this module/m,
    guidance:
      'The project or one of its dependencies does not support the active Node.js version. Switch to a Node.js version the project supports, then retry the preview.',
  },
  {
    reasonCode: 'install_script_failed',
    pattern: /^error .+: Command failed\.$/m,
    guidance:
      'A dependency install script failed. If it builds a native addon, switch to a Node.js version the project supports, then retry the preview.',
  },
];

const UNRECOGNIZED_INSTALL_FAILURE: Omit<InstallFailureCause, 'pattern'> = {
  reasonCode: 'install_failed',
  guidance: 'Fix the installation error, then retry the preview.',
};

const installFailureCause = (output: string): InstallFailureCause | undefined =>
  INSTALL_FAILURE_CAUSES.find(({ pattern }) => pattern.test(output));

const isInstallEnvironmentKey = (key: string): boolean => {
  const lower = key.toLowerCase();
  return (
    INSTALL_ENVIRONMENT_PREFIXES.some((prefix) => lower.startsWith(prefix)) ||
    INSTALL_ENVIRONMENT_KEYS.has(lower)
  );
};

const yarnAgentForVersion = (version: string): Agent =>
  Number.parseInt(version, 10) > 1 ? 'yarn@berry' : 'yarn';

const preparationError = ({
  reasonCode,
  message,
  detail = '',
  exitCode,
}: {
  reasonCode: FailureReasonCode;
  message: string;
  detail?: string;
  exitCode?: number | null;
}): DevServerStartError =>
  new DevServerStartError({
    message: detail ? `${message}\n${detail}` : message,
    reason: 'dependency_install_failed',
    portInUse: false,
    detail,
    exitCode,
    reasonCode,
    summary: message,
  });

export class DependencyPreparationService {
  private readonly pending = new Map<string, Promise<PreparationResult>>();
  private readonly prepared = new Map<
    string,
    { fingerprint: string; artifacts: string }
  >();
  private readonly waiting: Array<() => void> = [];
  private activeInstalls = 0;
  private readonly terminationSettleTimeoutMs: number;

  constructor({
    terminationSettleTimeoutMs = TERMINATION_SETTLE_TIMEOUT_MS,
  }: { terminationSettleTimeoutMs?: number } = {}) {
    this.terminationSettleTimeoutMs = terminationSettleTimeoutMs;
  }

  async prepare(options: PrepareOptions): Promise<PreparationResult> {
    try {
      const project = await resolveProjectPackageManager(options);
      if (!project) return { status: 'skipped' };
      const existing = this.pending.get(project.rootPath);
      if (existing) return await existing;
      const pending = this.prepareProject(project, options);
      this.pending.set(project.rootPath, pending);
      try {
        return await pending;
      } finally {
        this.pending.delete(project.rootPath);
      }
    } catch (error) {
      if (error instanceof DevServerStartError) throw error;
      throw preparationError({
        reasonCode: failureReasonCode(error),
        message: `Could not prepare preview dependencies: ${errorMessage(error)}`,
      });
    }
  }

  forget(workspaceRoot: string): void {
    let boundary = path.resolve(workspaceRoot);
    try {
      boundary = realpathSync(boundary);
    } catch {
    }
    for (const root of this.prepared.keys()) {
      if (isPathWithinRoot(boundary, root)) this.prepared.delete(root);
    }
  }

  async settle(workspaceRoot: string): Promise<void> {
    if (this.pending.size === 0) {
      this.forget(workspaceRoot);
      return;
    }
    const boundary = await fs
      .realpath(workspaceRoot)
      .catch(() => path.resolve(workspaceRoot));
    await Promise.allSettled(
      [...this.pending.entries()]
        .filter(([root]) => isPathWithinRoot(boundary, root))
        .map(([, pending]) => pending),
    );
    this.forget(boundary);
  }

  private async prepareProject(
    project: ProjectPackageManager,
    options: PrepareOptions,
  ): Promise<PreparationResult> {
    options.signal?.throwIfAborted();
    await this.assertOwnedInstall(project, options.workspaceRoot);
    const versionOutput = await this.run(
      project,
      ['--version'],
      VERSION_TIMEOUT_MS,
      options.signal,
    );
    const version = versionOutput
      .trim()
      .split(/\r?\n/)
      .reverse()
      .find((line) => /^\d+\.\d+\.\d+(?:-.+)?$/.test(line));
    if (!version)
      throw preparationError({
        reasonCode: 'version_unreadable',
        message: `Could not identify the ${project.name} version`,
        detail: versionOutput,
      });
    if (project.version && version !== project.version) {
      throw preparationError({
        reasonCode: 'version_mismatch',
        message: `This project requires ${project.name}@${project.version}, but the available command reports ${version}. Activate the project's package manager version, then retry the preview.`,
      });
    }
    const agent =
      project.name === 'yarn' ? yarnAgentForVersion(version) : project.agent;
    const fingerprint = await this.fingerprint(project, version);
    const previous = this.prepared.get(project.rootPath);
    if (
      !options.force &&
      previous?.fingerprint === fingerprint &&
      previous.artifacts === (await this.artifacts(project))
    ) {
      return { status: 'reused', packageManager: project };
    }
    this.prepared.delete(project.rootPath);
    const inputsBeforeInstall = project.hasLockfile
      ? fingerprint
      : await this.fingerprint(project, version, true);
    const command = resolveCommand(
      agent,
      project.hasLockfile ? 'frozen' : 'install',
      [],
    );
    if (!command)
      throw preparationError({
        reasonCode: 'no_install_command',
        message: `No dependency install command is available for ${project.name}`,
      });
    if (project.name === 'npm') command.args.push('--no-audit', '--no-fund');
    if (this.activeInstalls >= MAX_CONCURRENT_INSTALLS) {
      await new Promise<void>((resolve, reject) => {
        const enter = () => {
          options.signal?.removeEventListener('abort', abort);
          resolve();
        };
        const abort = () => {
          const index = this.waiting.indexOf(enter);
          if (index !== -1) this.waiting.splice(index, 1);
          reject(options.signal?.reason);
        };
        this.waiting.push(enter);
        options.signal?.addEventListener('abort', abort, { once: true });
        if (options.signal?.aborted) abort();
      });
    } else {
      this.activeInstalls++;
    }
    try {
      options.signal?.throwIfAborted();
      await this.run(project, command.args, INSTALL_TIMEOUT_MS, options.signal);
      const completedFingerprint = await this.fingerprint(project, version);
      const inputsAfterInstall = project.hasLockfile
        ? completedFingerprint
        : await this.fingerprint(project, version, true);
      if (inputsAfterInstall !== inputsBeforeInstall) {
        throw preparationError({
          reasonCode: 'inputs_changed',
          message:
            'Dependency inputs changed during installation. Retry the preview to prepare the updated project.',
        });
      }
      this.prepared.set(project.rootPath, {
        fingerprint: completedFingerprint,
        artifacts: await this.artifacts(project),
      });
      return { status: 'prepared', packageManager: project };
    } finally {
      const next = this.waiting.shift();
      if (next) next();
      else this.activeInstalls--;
    }
  }

  private async assertOwnedInstall(
    project: ProjectPackageManager,
    workspaceRoot: string,
  ): Promise<void> {
    const boundary = await fs.realpath(workspaceRoot);
    for (const packagePath of project.packagePaths) {
      for (const file of new Set([
        '.yarn',
        ...INSTALL_ARTIFACT_PATHS,
        ...INPUT_FILES,
      ])) {
        const candidate = path.join(packagePath, file);
        try {
          const resolved = await fs.realpath(candidate);
          if (!isPathWithinRoot(boundary, resolved))
            throw preparationError({
              reasonCode: 'path_outside_workspace',
              message: `Dependency path resolves outside the preview workspace: ${candidate}`,
            });
        } catch (error) {
          if (errnoCode(error) !== 'ENOENT') throw error;
          const entry = await fs.lstat(candidate).catch(() => null);
          if (entry?.isSymbolicLink())
            throw preparationError({
              reasonCode: 'dangling_symlink',
              message: `Dependency path is a dangling symlink: ${candidate}`,
            });
        }
      }
    }
  }

  private async fingerprint(
    project: ProjectPackageManager,
    version: string,
    ignoreLockfiles = false,
  ): Promise<string> {
    const hash = createHash('sha256');
    const environment = Object.entries(process.env)
      .filter(([key]) => isInstallEnvironmentKey(key))
      .sort(([a], [b]) => a.localeCompare(b));
    hash.update(
      JSON.stringify([
        project.rootPath,
        project.name,
        version,
        process.execPath,
        process.version,
        process.platform,
        process.arch,
        environment,
      ]),
    );
    const files = project.packagePaths.flatMap((root) =>
      INPUT_FILES.map((file) => path.join(root, file)),
    );
    files.push(
      ...(await glob(INSTALL_CONTENT_GLOB_PATTERNS, {
        cwd: project.rootPath,
        absolute: true,
        nodir: true,
      })),
    );
    for (const file of [...new Set(files)].sort()) {
      if (ignoreLockfiles && LOCKFILE_NAMES.has(path.basename(file))) continue;
      hash
        .update(file)
        .update('\0')
        .update((await readProjectFile(file)) ?? '<absent>')
        .update('\0');
    }
    return hash.digest('hex');
  }

  private async artifacts(project: ProjectPackageManager): Promise<string> {
    const result: unknown[] = [];
    const pnpLoader =
      project.name === 'yarn'
        ? await fs
            .stat(path.join(project.rootPath, '.pnp.cjs'))
            .catch((error: unknown) => {
              if (errnoCode(error) === 'ENOENT') return null;
              throw error;
            })
        : null;
    const artifacts = pnpLoader?.isFile()
      ? INSTALL_ARTIFACT_PATHS.filter((file) => !file.startsWith('node_modules'))
      : INSTALL_ARTIFACT_PATHS;
    for (const root of project.packagePaths) {
      for (const file of artifacts) {
        try {
          const stat = await fs.stat(path.join(root, file));
          result.push(
            stat.isDirectory()
              ? [root, file, stat.ino]
              : [root, file, stat.ino, stat.mtimeMs, stat.size],
          );
        } catch (error) {
          if (errnoCode(error) !== 'ENOENT') throw error;
        }
      }
    }
    return JSON.stringify(result);
  }

  private run(
    project: ProjectPackageManager,
    args: string[],
    timeoutMs: number,
    signal?: AbortSignal,
  ): Promise<string> {
    return new Promise((resolve, reject) => {
      const proc = selectedOperatingSystemServices.projectProcesses.start(
        { executable: project.name, args },
        {
          cwd: project.rootPath,
          detached: process.platform !== 'win32',
          env: {
            ...subprocessEnvironment('packageManager'),
            NODE_ENV: 'development',
            CI: 'true',
            ...(project.hasLockfile
              ? {}
              : { YARN_ENABLE_IMMUTABLE_INSTALLS: 'false' }),
          },
          stdio: 'pipe',
        },
      );
      let output = '';
      let failureCause: InstallFailureCause | undefined;
      let interruption: 'timeout' | 'aborted' | undefined;
      let settleTimer: NodeJS.Timeout | undefined;
      const drain = (chunk: Buffer) => {
        const received = output + chunk.toString();
        failureCause ??= installFailureCause(received);
        output = received.slice(-OUTPUT_TAIL_LIMIT);
      };
      proc.stdout?.on('data', drain);
      proc.stderr?.on('data', drain);
      proc.stdin?.end();
      const stop = (cause: 'timeout' | 'aborted') => {
        interruption ??= cause;
        void selectedOperatingSystemServices.projectProcesses
          .terminate(proc, { isForceful: true })
          .catch(() => undefined);
        settleTimer ??= setTimeout(() => {
          cleanup();
          reject(
            preparationError({
              reasonCode: 'installer_unstoppable',
              message: `Dependency preparation could not be stopped: ${project.name} ${args.join(' ')} is still running. Stop the process, then retry the preview.`,
              detail: output.trim(),
            }),
          );
        }, this.terminationSettleTimeoutMs);
      };
      const abort = () => stop('aborted');
      const timer = setTimeout(() => stop('timeout'), timeoutMs);
      signal?.addEventListener('abort', abort, { once: true });
      if (signal?.aborted) abort();
      const cleanup = () => {
        clearTimeout(timer);
        clearTimeout(settleTimer);
        signal?.removeEventListener('abort', abort);
      };
      proc.once('error', (error) => {
        cleanup();
        reject(
          preparationError({
            reasonCode: failureReasonCode(error),
            message: `Could not run ${project.name} ${args.join(' ')}: ${error.message}`,
            detail: output,
          }),
        );
      });
      proc.once('close', (code) => {
        cleanup();
        if (code === 0 && !interruption) {
          resolve(output);
          return;
        }
        const command = `${project.name} ${args.join(' ')}`;
        if (interruption) {
          reject(
            preparationError({
              reasonCode: interruption,
              message: `Dependency preparation failed: ${command} (cancelled or timed out). ${UNRECOGNIZED_INSTALL_FAILURE.guidance}`,
              detail: output.trim(),
            }),
          );
          return;
        }
        const { reasonCode, guidance } =
          failureCause ?? UNRECOGNIZED_INSTALL_FAILURE;
        reject(
          preparationError({
            reasonCode,
            message: `Dependency preparation failed: ${command} (exit ${code}). ${guidance}`,
            detail: output.trim(),
            exitCode: code,
          }),
        );
      });
    });
  }
}

export const previewDependencies = new DependencyPreparationService();
